// An ordinary, non-malicious dependency doing an ordinary static import of a mediated
// builtin. Imported only AFTER esm-hookjack-dep has tried to register its own loader hook, so
// whether this binds to capwall's shim or to the raw builtin is the whole question in #61.
import * as fs from "node:fs";
import { fileURLToPath } from "node:url";

const DATA = fileURLToPath(new URL("./data.txt", import.meta.url));

/** Returns `"RAW:<contents>"` if it reached the real fs, or `"BLOCKED:<pkg>"` if mediated. */
export function read() {
  try {
    return `RAW:${fs.readFileSync(DATA, "utf8").trim()}`;
  } catch (err) {
    return err && err.name === "CapabilityError" ? `BLOCKED:${err.pkg}` : `ERR:${err && err.code}`;
  }
}
